#!/usr/bin/env node
/**
 * Branch-preview-only Wrangler config adapter.
 *
 * Nitro's autogenerated Workers config omits the `previews` property required
 * by Cloudflare's `wrangler preview` command. This script patches the GENERATED
 * output, never the checked-in production configuration or deployed Worker.
 *
 * Call after the complete Vite/Nitro build and before `wrangler preview`.
 */
import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

const output = resolve(".output/server/wrangler.json");
let config;
try {
  config = JSON.parse(await readFile(output, "utf8"));
} catch (error) {
  console.error("Worker preview config missing or invalid; build must succeed first.", error);
  process.exitCode = 1;
  throw error;
}
if (!config || typeof config !== "object" || Array.isArray(config)) {
  throw new Error("Generated Worker config must be a JSON object.");
}
if (!config.main && !config.assets) {
  throw new Error("Generated Worker config has neither script nor assets; refusing to patch.");
}
if (config.previews !== undefined && (config.previews === null || typeof config.previews !== "object" || Array.isArray(config.previews))) {
  throw new Error("Generated Worker previews setting is malformed.");
}
const updated = { ...config, previews: config.previews ?? {} };
await writeFile(output, JSON.stringify(updated, null, 2) + "\n", "utf8");
const checked = JSON.parse(await readFile(output, "utf8"));
if (!checked.previews || typeof checked.previews !== "object" || !checked.main && !checked.assets) {
  throw new Error("Generated Wrangler preview configuration failed readback.");
}
console.log("Branch-preview Wrangler config VERIFIED: previews block present, generated config only.");
